-- taken from https://github.com/leoaviana/QuestTradutor

local function IMM_splitstr (inputstr, sep)
    if sep == nil then
            sep = "%s"
    end
    local t={}
    for str in string.gmatch(inputstr, "([^"..sep.."]+)") do
            table.insert(t, str)
    end
    return t
 end
  
 
local function IMM_IsQuestAvailableForPlayerRace(questId)
    if(IMM_QuestRaceList[questId]) then
       local bs = IMM_QuestRaceList[questId];
       local playerRace, playerRaceEn = UnitRace("player");
 
       if(bs == "0" or bs == "1791") then
          return true; -- the quest is available for all races...
       end  
 
       if(IMM_PlayerRaceList[tostring(playerRaceEn)]) then
          local qtr_raceInfo =  IMM_splitstr(IMM_PlayerRaceList[tostring(playerRaceEn)], ","); 
          local raceId = qtr_raceInfo[1];
          local IsHorde = qtr_raceInfo[2]; 
 
          if(bs == raceId) then
             return true;
          end
 
          if(bs == "690") then  -- 690 means the quest is available for all horde races
             if(IsHorde == "true") then
                return true;
             end
          end  
          
          if(bs == "1101") then -- 1101 means the quest is available for all alliance races
             if(IsHorde == "false") then
                return true;
             end
          end
       end
 
    end
 
    return false;
       
 end
 
local function IMM_isFromTargetNPC(questId, targetNPC) 
    if (IMM_QuestGiverList[tostring(targetNPC)]) then
       local q_lists=IMM_QuestGiverList[tostring(targetNPC)];
       q_i=string.find(q_lists, ",");
       if ( string.find(q_lists, ",")==nil ) then
          -- only 1 questID to this npcID
          quest_ID=tonumber(q_lists);
          if(tonumber(questId) == quest_ID) then
             return true;
          else
             return false;
          end
       else
          local QTR_table=IMM_split(q_lists, ",", -1);
          for ii,vv in ipairs(QTR_table) do
             if(tonumber(vv) == tonumber(questId)) then
                return true;
             end
          end
       end 
    end
    return false;
 end
 
local function IMM_split(str, c, t) 
    local aCount = 0;
    local array = {};
    local a = string.find(str, c);
    while a do
       if(t == -1) then
          if(IMM_IsQuestAvailableForPlayerRace(string.sub(str, 1, a-1))) then 
             aCount = aCount + 1;
             array[aCount] = string.sub(str, 1, a-1); 
          end
       else
          if(IMM_isFromTargetNPC(string.sub(str, 1, a-1), t)) then
             if(IMM_IsQuestAvailableForPlayerRace(string.sub(str, 1, a-1))) then 
                   aCount = aCount + 1;
                   array[aCount] = string.sub(str, 1, a-1); 
             end
          end
       end 
 
       str=string.sub(str, a+1);
       a = string.find(str, c);
    end
 
    if(t == -1) then
       if(IMM_IsQuestAvailableForPlayerRace(str)) then 
          aCount = aCount + 1;
          array[aCount] = str; 
       end
    else
       if(IMM_isFromTargetNPC(str, t)) then
          if(IMM_IsQuestAvailableForPlayerRace(str)) then 
                aCount = aCount + 1;
                array[aCount] = str; 
          end
       end
    end
 
    return array;
  end

 function ImmersionAPI:GetQuestID()
    local q_title = GetTitleText();  
    local q_i = 1;
    quest_ID = 0;
    if ( quest_ID==0 or quest_ID==nil ) then
       -- search in QuestLog
       while GetQuestLogTitle(q_i) do
          local questTitle, level, questTag, suggestedGroup, isHeader, isCollapsed, isComplete, isDaily, questID = GetQuestLogTitle(q_i)
          if ( not isHeader ) then
             if ( q_title == questTitle ) then 
               quest_ID=questID;
               break;
            end
         end
        q_i = q_i + 1;
       end
    end
 
    if ( quest_ID == 0 or quest_ID==nil) then 
       if ( quest_ID == 0 ) then
          if (QuestTranslator_QuestList[q_title]) then
             local q_lists=QuestTranslator_QuestList[q_title];
             q_i=string.find(q_lists, ","); 
             if ( string.find(q_lists, ",")==nil ) then
                -- only 1 questID to this title
                quest_ID=tonumber(q_lists); 
             else
                -- multiple questIDs - get first, available (not completed) questID from QuestLists and which the NPC is in the target from QuestGiverList
                
                -- get target NPC id
  
                local a= "";
                local targetNPC = 0;
 
                if(UnitGUID("target") == nil or UnitGUID("target") == 0) then
                   targetNPC = -1;
                else
                   local guid = UnitGUID("target");
                   local x = tonumber(guid:sub(5,5), 16);
                   local unitType = x % 8; 
 
                   if(not (unitType == 0)) then -- not player
                      a = strsub(guid,9,12); 
                      targetNPC = tonumber(a,16);
                   else
                      targetNPC = -1;
                   end
 
                end 
 
                local QTR_table=IMM_split(q_lists, ",", targetNPC);
                
                if(QTR_table == nil) then
                   return 0;
                end
 
                local QTR_multiple = "";
                local QTR_Center=""; 
                local IMM_QUESTSTATUS = {}; --workaround
 
                for ii,vv in ipairs(QTR_table) do
                   if (not (IMM_QUESTSTATUS[vv] == "OK")) then
                      if (QTR_Center=="") then
                          QTR_Center=vv;
                      else
                          QTR_multiple = QTR_multiple .. ", " .. vv;
                      end
                   end
                   if(IMM_QUESTSTATUS[vv] == "NEXTQUEST") then
                      QTR_Center =vv;
                      QTR_multiple = "";
                      break;
                   end
                end
                if ( string.len(QTR_Center)>0 ) then
                   quest_ID=tonumber(QTR_Center);
                   if ( string.len(QTR_multiple)>0 ) then
                      QTR_multiple = " (" .. string.sub(QTR_multiple, 3) .. ")";
                      --print("Essa quest possui duplicatas, provavelmente sua tradução pode estar incorreta, aceite-a e leia no Quest Log (aperte L)");
                      --QuestTranslator_QuestWarning2:SetText(QuestTranslator_Messages.multipleID .. QTR_multiple);
                   end
                end
             end
          end
       end
    end   
    return (quest_ID);
 end 
